B.qJ=s(["\u0b9e\u0bbe\u0baf\u0bbf.","\u0ba4\u0bbf\u0b99\u0bcd.","\u0b9a\u0bc6\u0bb5\u0bcd.","\u0baa\u0bc1\u0ba4.","\u0bb5\u0bbf\u0baf\u0bbe.","\u0bb5\u0bc6\u0bb3\u0bcd.","\u0b9a\u0ba9\u0bbf"],t.s)
B.a9j=s(['Al abrir la app por primera vez toca "Crear mi negocio".',"Ponle un nombre a tu negocio, tu correo y una contrase\xf1a.",'Un operador te entregar\xe1 un "c\xf3digo de activaci\xf3n". M\xe9telo para empezar a usar la app.',"Este tel\xe9fono queda como el due\xf1o del negocio."],t.s)
B.ajq=new A.e_(B.a9j,B.CN,"Primeros pasos")
B.a6X=s(["Al entrar ves un resumen de tu negocio: ventas, ganancias y caja del d\xeda.","El men\xfa inferior te lleva a las secciones principales: Resumen, Inventario, Vender, Caja y Ganancias.","El men\xfa (\u2630) de arriba a la izquierda abre todas las opciones del negocio.","El bot\xf3n flotante (FAB) abajo a la derecha te da acceso r\xe1pido a las acciones m\xe1s usadas: Inventario Diario, Publicar lista, Calculadora, Sincronizar y m\xe1s.",u.O],t.s)
B.ajC=new A.e_(B.a6X,B.ws,"La pantalla de inicio (Resumen)")
B.a9A=s(["Aqu\xed agregas los productos que vendes y su stock.","Ponles nombre, precio de compra y de venta, y categor\xeda.","Puedes organizar tu mercanc\xeda en almacenes y ver cu\xe1nto te queda de cada producto."],t.s)
B.ajf=new A.e_(B.a9A,B.cl,"Inventario")
B.a8i=s(["Crea categor\xedas para organizar tus productos: Bebidas, Comestibles, Limpieza, etc.","Asigna cada producto a una categor\xeda para mantener el inventario ordenado.","Las categor\xedas aparecen al crear o editar un producto."],t.s)
B.ajx=new A.e_(B.a8i,B.hn,"Categor\xedas de productos")
B.aa5=s(["Elige el producto, la cantidad y el m\xe9todo de pago.","Al vender, el stock se descuenta solo.","Cada venta queda guardada y aparece en Ganancias."],t.s)
B.ajd=new A.e_(B.aa5,B.mO,"Vender")
B.a9Z=s(["Revisa el resumen de ventas de cada d\xeda: ingresos, ganancias y unidades vendidas.","Toca un d\xeda para ver el detalle de cada venta realizada.","Puedes eliminar una venta desde aqu\xed si fue registrada por error (se devuelve el stock)."],t.s)
B.ajs=new A.e_(B.a9Z,B.ki,"Inventario Diario")
B.a6i=s(["Sirve para hacer el arqueo de caja: cu\xe1nto dinero hay en el caj\xf3n.","Registra las monedas y billetes que hay y deja constancia de cada arqueo."],t.s)
B.ajk=new A.e_(B.a6i,B.bC,"Caja")
B.a9N=s(["Registra todos los gastos del negocio: compras, servicios, salarios, etc.","As\xed las ganancias se calculan descontando lo que se gasta."],t.s)
B.ajz=new A.e_(B.a9N,B.wt,"Gastos")
B.abY=s(["Registra productos da\xf1ados, vencidos o perdidos.","Selecciona el producto, la cantidad y el motivo de la merma.","Las mermas quedan registradas para que tengas control de las p\xe9rdidas."],t.s)
B.ajn=new A.e_(B.abY,B.iq,"Mermas")
B.a9n=s(["Registra tus cuentas bancarias o de pago m\xf3vil para recibir transferencias.","Ponles un alias, nombre del banco y n\xfamero de tarjeta.","Puedes subir una imagen del QR para que los clientes la vean al pagar.",'La cuenta marcada como predeterminada se muestra al seleccionar "Transferencia" como m\xe9todo de pago.'],t.s)
B.ajh=new A.e_(B.a9n,B.d8,"Cuentas de transferencia")
B.ac2=s(['Cada vendedor usa la app "SSPV Ventas" en su propio tel\xe9fono.','En la pantalla de tu tel\xe9fono est\xe1 el "ID de este dispositivo": es la identidad de tu negocio.',"P\xeddele al vendedor el ID que muestra su app al abrirla y reg\xedstralo aqu\xed con su nombre.","Elige desde qu\xe9 punto de venta (almac\xe9n) vender\xe1.","Al quitar un vendedor, se elimina de tu tel\xe9fono y de la nube: su app dejar\xe1 de sincronizar con tu negocio."],t.s)
B.ajc=new A.e_(B.ac2,B.CG,"Vendedores (dispositivos)")
B.ab1=s(["Organiza tu mercanc\xeda en varios lugares: almac\xe9n central, punto de venta, etc.","Haz traslados para mover stock de un lugar a otro."],t.s)
B.ajl=new A.e_(B.ab1,B.wv,"Almacenes y traslados")
B.aaQ=s([u.B,u.I,"Guarda un historial de los \xfaltimos c\xe1lculos realizados."],t.s)
B.ajg=new A.e_(B.aaQ,B.kg,"Calculadora")
B.abv=s(["Sube tu inventario, ventas y gastos a la nube para tenerlos a salvo.",'Con "Sincronizar" tu informaci\xf3n viaja al servidor de respaldo.',"Sirve para que los vendedores bajen el inventario actualizado del negocio.","La app sincroniza sola cuando tiene internet."],t.s)
B.ajv=new A.e_(B.abv,B.mY,"Sincronizaci\xf3n en la nube")
B.aaO=s(["Comparte tu lista de precios con tus clientes por WhatsApp.","Personaliza la plantilla de publicaci\xf3n con el nombre del negocio, encabezado, pie de p\xe1gina y datos de contacto.","Vista previa en vivo para ver c\xf3mo quedar\xe1 el mensaje antes de compartirlo."],t.s)
B.aje=new A.e_(B.aaO,B.mV,"Publicar en WhatsApp")
B.aaf=s(["Haz un backup para guardar una copia de todo tu negocio en el tel\xe9fono.","Si no tienes internet, comparte el inventario por WhatsApp y podr\xe1s importarlo donde necesites.","Puedes restaurar una copia si cambias de tel\xe9fono o pierdes datos."],t.s)
B.ajA=new A.e_(B.aaf,B.mM,"Respaldo de datos")
B.a9K=s(["Cambia los colores de la app y el modo claro u oscuro.","Configura la moneda por defecto (CUP, USD, EUR) y las tasas de cambio."],t.s)
